--
-- Name: check_vote_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_vote_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    valid_session BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM   voting_sessions
        WHERE  voter_id           = NEW.voter_id
          AND  biometric_verified = TRUE
          AND  used               = FALSE
          AND  expires_at         > NOW()
    ) INTO valid_session;

    IF NOT valid_session THEN
        RAISE EXCEPTION
            'SECURITY VIOLATION: vote rejected â€” no valid biometric session for voter %',
            NEW.voter_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: enable_election(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.enable_election(IN p_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE elections SET is_active = FALSE;
    UPDATE elections SET is_active = TRUE WHERE id = p_id;
    UPDATE election_settings SET value = p_id::text WHERE key = 'active_election';
END;
$$;


--
-- Name: reset_election(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.reset_election()
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM voting_sessions;
    DELETE FROM vote;
    UPDATE voters SET has_voted = FALSE, card_active = TRUE,
                      election_cycle = (SELECT current_cycle + 1 FROM election_config WHERE id = 1);
    UPDATE election_config SET current_cycle = current_cycle + 1 WHERE id = 1;
    RAISE NOTICE 'Election reset. New cycle: %', (SELECT current_cycle FROM election_config WHERE id = 1);
END;
$$;


--
-- Name: reset_election_votes(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.reset_election_votes(IN p_election_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM voting_sessions WHERE election_id = p_election_id;
    DELETE FROM vote WHERE election_id = p_election_id;
    UPDATE elections SET election_cycle = election_cycle + 1 WHERE id = p_election_id;
END;
$$;


--
-- Name: set_language(character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.set_language(IN p_lang character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE election_settings SET value = p_lang WHERE key = 'language';
END;
$$;


