--
-- Name: voter_election_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.voter_election_status AS
 SELECT v.voter_id,
    v.name,
    s.name AS state_name,
    ls.name AS ls_constituency,
    vs.name AS vs_constituency,
    COALESCE(vs.district_name, ls.district_name, ''::character varying) AS district,
        CASE
            WHEN (v1.voter_id IS NOT NULL) THEN true
            ELSE false
        END AS voted_pm,
        CASE
            WHEN (v2.voter_id IS NOT NULL) THEN true
            ELSE false
        END AS voted_cm,
        CASE
            WHEN (v3.voter_id IS NOT NULL) THEN true
            ELSE false
        END AS voted_municipality
   FROM ((((((public.voters v
     LEFT JOIN public.states s ON ((s.id = v.state_id)))
     LEFT JOIN public.constituencies ls ON ((ls.id = v.ls_constituency_id)))
     LEFT JOIN public.constituencies vs ON ((vs.id = v.vs_constituency_id)))
     LEFT JOIN public.vote v1 ON ((((v1.voter_id)::text = (v.voter_id)::text) AND (v1.election_id = 1))))
     LEFT JOIN public.vote v2 ON ((((v2.voter_id)::text = (v.voter_id)::text) AND (v2.election_id = 2))))
     LEFT JOIN public.vote v3 ON ((((v3.voter_id)::text = (v.voter_id)::text) AND (v3.election_id = 3))));


