--
-- Name: voter_full_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.voter_full_detail AS
 SELECT v.voter_id,
    v.name AS voter_name,
    wl.name AS ward,
    wl.ward_number,
    p.name AS panchayat,
    c.name AS council,
    vs.name AS cm_constituency,
    vs.district_name AS cm_district,
    ls.name AS pm_constituency,
    d.name AS district,
    s.name AS state,
    v.card_active,
    v.fingerprint_enrolled,
        CASE
            WHEN (v.photo IS NOT NULL) THEN ((('data:'::text || (v.photo_type)::text) || ';base64,'::text) || encode(v.photo, 'base64'::text))
            ELSE NULL::text
        END AS photo_data_url,
        CASE
            WHEN (v1.voter_id IS NOT NULL) THEN 'Voted'::text
            ELSE 'Not voted'::text
        END AS pm_status,
        CASE
            WHEN (v2.voter_id IS NOT NULL) THEN 'Voted'::text
            ELSE 'Not voted'::text
        END AS cm_status,
    ((( SELECT count(*) AS count
           FROM public.vote vm
          WHERE (((vm.voter_id)::text = (v.voter_id)::text) AND (vm.election_id = 3))))::text || '/4 tiers'::text) AS municipality_status
   FROM (((((((((public.voters v
     LEFT JOIN public.states s ON ((s.id = v.state_id)))
     LEFT JOIN public.constituencies ls ON ((ls.id = v.ls_constituency_id)))
     LEFT JOIN public.constituencies vs ON ((vs.id = v.vs_constituency_id)))
     LEFT JOIN public.councils c ON ((c.id = v.council_id)))
     LEFT JOIN public.panchayats p ON ((p.id = v.panchayat_id)))
     LEFT JOIN public.wards_local wl ON ((wl.id = v.ward_local_id)))
     LEFT JOIN public.districts d ON ((d.id = c.district_id)))
     LEFT JOIN public.vote v1 ON ((((v1.voter_id)::text = (v.voter_id)::text) AND (v1.election_id = 1) AND (v1.municipality_tier IS NULL))))
     LEFT JOIN public.vote v2 ON ((((v2.voter_id)::text = (v.voter_id)::text) AND (v2.election_id = 2) AND (v2.municipality_tier IS NULL))));


